function toggle(list, value) {
  return list.includes(value) ? list.filter((v) => v !== value) : [...list, value];
}
function parseDigits(raw) {
  let d = raw.replace(/\D/g, "");
  d = d.replace(/^0+(?=\d)/, "");
  return d === "" ? "0" : d;
}
function fmt(n) {
  return Number.isInteger(n) ? n : Math.round(n * 10) / 10;
}
// none -> asc -> desc -> none
function nextSort(field, current) {
  if (current.field !== field) return { field, dir: "asc" };
  if (current.dir === "asc") return { field, dir: "desc" };
  return { field: null, dir: "asc" };
}
function getModelRarity(item) { return MODEL_META[item.model]?.rarity ?? 0; }
function getBgRarity(item) { return BACKGROUNDS.find((b) => b.name === item.bg)?.rarity ?? 0; }
function getSymbolRarity(item) { return SYMBOLS.find((s) => s.name === item.symbol)?.rarity ?? 0; }
function sortListings(list, key) {
  if (!key) return list;
  const arr = [...list];
  switch (key) {
    case "placement_asc": return arr.sort((a, b) => a.id - b.id);
    case "placement_desc": return arr.sort((a, b) => b.id - a.id);
    case "price_asc": return arr.sort((a, b) => a.price - b.price);
    case "price_desc": return arr.sort((a, b) => b.price - a.price);
    case "modelRarity_asc": return arr.sort((a, b) => getModelRarity(a) - getModelRarity(b));
    case "modelRarity_desc": return arr.sort((a, b) => getModelRarity(b) - getModelRarity(a));
    case "bgRarity_asc": return arr.sort((a, b) => getBgRarity(a) - getBgRarity(b));
    case "bgRarity_desc": return arr.sort((a, b) => getBgRarity(b) - getBgRarity(a));
    case "symbolRarity_asc": return arr.sort((a, b) => getSymbolRarity(a) - getSymbolRarity(b));
    case "symbolRarity_desc": return arr.sort((a, b) => getSymbolRarity(b) - getSymbolRarity(a));
    case "number_asc": return arr.sort((a, b) => parseInt(a.num, 10) - parseInt(b.num, 10));
    default: return arr;
  }
}

