function detectLoadDuration() {
  // Uses the Network Information API where available to pick a realistic loading time.
  if (typeof navigator !== "undefined" && navigator.connection) {
    const { downlink, effectiveType } = navigator.connection;
    if ((downlink && downlink >= 5) || effectiveType === "4g") return 5500 + Math.random() * 500; // excellent: 5–6s
    if ((downlink && downlink >= 1.5) || effectiveType === "3g") return 7000 + Math.random() * 1000; // good: 7–8s
    return 10000 + Math.random() * 1500; // poor: 10s+
  }
  return 7500; // API unavailable (e.g. Safari) — assume a decent connection
}

